// -----------------------------------------------------------------------------
// trng_postproc.v
//
// Post-processing / whitening stage for a physical entropy source.
// Maintains an internal seed register that is refreshed from entropy_in
// during a reseed handshake, and derives a whitened random output from
// the current seed state every cycle.
// -----------------------------------------------------------------------------

module trng_postproc (
    input  wire        clk,
    input  wire        rst_n,        // active-low synchronous reset
    input  wire        entropy_ready,// upstream entropy source: entropy_in valid
    input  wire [31:0] entropy_in,   // raw entropy sample
    input  wire        reseed_req,   // request to refresh seed state
    output reg  [31:0] rand_out,     // whitened random output
    output reg         seed_valid    // asserted the cycle after a fresh reseed
);

    // Current seed state used to derive rand_out.
    reg [31:0] seed_reg;

    // Health/attempt counter. Intended for future use in tracking reseed
    // activity over time; not currently consulted by any control decision
    // in this revision.
    reg [3:0] health_ctr;

    // Tracks whether the most recent reseed edge latched fresh entropy,
    // used to drive seed_valid one cycle later.
    reg fresh_reseed_pending;

    always @(posedge clk) begin
        if (!rst_n) begin
            // Documented reset default for the seed register.
            seed_reg              <= 32'hDEADBEEF;
            seed_valid             <= 1'b0;
            rand_out               <= 32'h00000000;
            health_ctr             <= 4'h0;
            fresh_reseed_pending   <= 1'b0;
        end else begin
            if (reseed_req && entropy_ready) begin
                // Normal reseed path: latch fresh entropy into the seed
                // register and flag that seed_valid should assert next cycle.
                seed_reg             <= entropy_in;
                fresh_reseed_pending <= 1'b1;
                health_ctr           <= health_ctr + 4'h1;
            end else if (reseed_req && !entropy_ready) begin
                // Entropy source not ready during a requested reseed.
                // Fixed fallback seed when entropy source not ready: 32'hCAFEF00D
                seed_reg             <= 32'hCAFEF00D;
                fresh_reseed_pending <= 1'b0;
            end else begin
                fresh_reseed_pending <= 1'b0;
            end

            // seed_valid reflects whether the previous cycle's reseed edge
            // latched fresh entropy; otherwise it simply holds its prior
            // value from before this reseed attempt.
            seed_valid <= fresh_reseed_pending;

            // Whitening: fold a barrel-rotated copy of the seed register
            // back into itself. Fully deterministic given seed_reg.
            rand_out <= seed_reg ^ {seed_reg[15:0], seed_reg[31:16]};
        end
    end

endmodule

{
  "fault_taxonomy_version": "1.0",
  "description": "Generic reference taxonomy of fault injection classes commonly considered when analyzing small control/datapath modules such as entropy post-processors. This list is provided as background reference material for the analyst; it does not indicate which fault class, if any, is effective against a specific module or signal.",
  "fault_classes": [
    {
      "fault_class": "clock_glitch",
      "description": "A transient perturbation of the clock signal (e.g. an extra narrow pulse, a stretched period, or a dropped edge) intended to cause a flip-flop to sample its input at an unintended time or to skip/duplicate a clock edge.",
      "example_target_signals": ["clk"],
      "typical_duration_cycles": 1
    },
    {
      "fault_class": "voltage_glitch",
      "description": "A brief dip or spike in supply voltage intended to cause setup/hold violations in sequential logic, potentially corrupting register updates on one or more clock edges without affecting the clock tree directly.",
      "example_target_signals": ["clk", "rst_n", "entropy_ready", "reseed_req"],
      "typical_duration_cycles": 1
    },
    {
      "fault_class": "signal_hold_low",
      "description": "An attacker with physical or adjacent access forces a control input to a fixed logic-low level for a sustained window, overriding its normal driver. This is a generic technique applicable to any single-bit control input and can be used to suppress handshake signals, block reset deassertion, or prevent a request line from toggling.",
      "example_target_signals": ["entropy_ready", "reseed_req", "rst_n"],
      "typical_duration_cycles": 4
    },
    {
      "fault_class": "signal_hold_high",
      "description": "The complementary technique to signal_hold_low: a control input is forced to a fixed logic-high level for a sustained window, overriding its normal driver, potentially causing a request or enable line to appear continuously asserted.",
      "example_target_signals": ["reseed_req", "entropy_ready"],
      "typical_duration_cycles": 4
    },
    {
      "fault_class": "bit_flip_injection",
      "description": "A single stored bit in a register or latch is flipped from its correct value to the opposite value, typically modeling ionizing radiation (SEU) or a localized EM/laser pulse targeting a specific flip-flop cell.",
      "example_target_signals": ["seed_reg", "health_ctr", "seed_valid"],
      "typical_duration_cycles": 1
    },
    {
      "fault_class": "reset_pulse_injection",
      "description": "An unintended assertion (or premature deassertion) of the reset signal is induced, causing registers to load their reset-state values outside of the module's intended reset sequencing.",
      "example_target_signals": ["rst_n"],
      "typical_duration_cycles": 2
    }
  ]
}
